import sympy as sp
t, a, b = sp.symbols('t a b', positive=True)
def area(X, Y):
    return sp.simplify(sp.integrate(X*sp.diff(Y,t) - Y*sp.diff(X,t),(t,0,2*sp.pi))/2)
assert sp.simplify(area(a*sp.cos(t), b*sp.sin(t)) - sp.pi*a*b) == 0
assert sp.simplify(area(sp.cos(t)**3, sp.sin(t)**3) - 3*sp.pi/8) == 0
